-- [SPMPIE-26827]允许rsku绑定在同cspu的多个vmodel上,by 2025-11-21
-- 问：如果我说一个r所对应的多个vmodleid一定分属于不同的vitemid，这个对吗？答：对，一个rmodel一定对应的是不同的 vitem，这个我们做了限制
CREATE TEMPORARY VIEW vsku_tag_${grass_region_without_quote} AS
select
     vitem_id
    ,publish_local_date
from srdi_mart.dim_sr_data_warehouse_vsku_vitem
WHERE grass_region IN (${grass_region})
and local_date = data_infra.max_pt('srdi_mart.dim_sr_data_warehouse_vsku_vitem', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW vsku_metrics_${grass_region_without_quote} AS
select
     vitem_id
    ,order_cnt_nd as vsku_order_cnt_nd
from srdi_mart.dws_sr_data_warehouse_vsku_vitem_nd
WHERE grass_region IN (${grass_region})
and local_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_vsku_vitem_nd', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW vsku_rmodel_mapping_${grass_region_without_quote} AS
select
     cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,vmodel_id
    ,vitem_id
    ,vshop_id
from paimon.srdi_mart.ods_sr_data_warehouse_vsku_model_mapping
where grass_region in (${grass_region}) and status=1
-- 剔除 live test 的vitem
and (case
      when ${grass_region}='PH' then vitem_id not in (28220985573,25089553214,24439553114)
      when ${grass_region}='TH' then vitem_id not in (25690469056,27623537795,29873533900)
      else true
    end)
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_vsku_model_mapping_hf
partition(grass_region = ${grass_region}, local_date, local_hour, regional_date,regional_hour)
SELECT
     cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,vmodel_id
    ,vitem_id
    ,vshop_id
    ,case
        when vsku_publish_days <=14 then 1
        when vsku_publish_days <=28 then 2
        else 3
     end as vsku_grow_period
    ,vsku_publish_local_date
    ,vsku_order_cnt_nd

    ,date(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"yyyy-MM-dd")) as local_date
    ,cast(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"HH") as int) as local_hour
    ,cast(${regional_date} as date) as regional_date
    ,cast(${regional_hour} as int) as regional_hour
from(
    select
         a.*
        ,if(publish_local_date is null,1,DATEDIFF(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"yyyy-MM-dd"),publish_local_date)+1 ) as vsku_publish_days
        ,publish_local_date as vsku_publish_local_date
        ,coalesce(vsku_order_cnt_nd,0) as vsku_order_cnt_nd
    FROM vsku_rmodel_mapping_${grass_region_without_quote} a
    left join vsku_tag_${grass_region_without_quote} b on a.vitem_id=b.vitem_id
    left join vsku_metrics_${grass_region_without_quote} c on a.vitem_id=c.vitem_id
) d
;
